INSERT INTO public.registration_fees (id, edition_id, category, amount_inr, amount_usd, indian_display, foreign_display, tax_note, payment_instructions, sort_order, status) VALUES
('20270011-0000-4000-8000-000000000001', '20270000-0000-4000-8000-000000000001', 'Student/ Research Scholar', 4000, 100, '4000 INR/-', '100 USD', 'All fees are inclusive of taxes.', '{"taxNote":"All fees are inclusive of taxes.","paymentMethodsNote":"Payment can be made via Bank Transfer (NEFT/RTGS/Net) or UPI. Credit card payments are not accepted.","upiId":"iemt@iob","bankTransfer":{"bankName":"Indian Overseas Bank","partyName":"Institute of Engineering & Management Trust","accountNo":"164201000000488","accountType":"Savings","ifscCode":"IOBA0001642","branch":"Sector- V","swiftCode":"IOBAINBB193","micr":"700020049"},"policies":["Final submissions require regular registration, with at least one author per paper registering at the regular rate.","If more than one author from a paper attends to present, the requisite registration amount must be paid by each attending author. This includes the registration kit and food coupons for two days.","If an author has more than one accepted paper, each paper must be registered separately."],"confirmationEmailInstruction":"After payment, you must send an email with a screenshot of the transaction to metaSphere2026@iem.edu.in. Your email must include your Paper ID and Paper Title. When making the transfer, please also mention the Paper ID in the transaction remarks.","cancellationPolicy":"There will be no cancellation after Registration."}'::jsonb, 1, 'published'),
